transitions.transitionKernelCode:
const indianOpen = input.OpenIndianFlowbind[0].units;
const position = input.ReleasedFlowbind[0].units + indianOpen + input.OpenGermanFlowbind[0].units;
const gap = parameters.flowbind_target_level - position;
const order = Math.ceil(gap / parameters.indian_flowbind_moq) * parameters.indian_flowbind_moq;
return { OpenIndianFlowbind: [{ units: indianOpen + order }] };

const order = input.DueSonicFlowOrders[0];
const needed = order.units;
return {
  ReleasedFlowbind: [{ units: input.ReleasedFlowbind[0].units - needed }],
  ReleasedSonaflozin: [{ units: input.ReleasedSonaflozin[0].units - needed }],
  SonicFlowInProduction: [{ units: needed, wait_days: order.wait_days }]
};

metrics.code:
const waiting = state.places.DueSonicFlowOrders.tokens.reduce((sum, order) => sum + order.wait_days, 0);
const started = state.places.SonicFlowInProduction.tokens.reduce((sum, order) => sum + order.wait_days, 0);
return waiting + started;
